using System;
using System.Data;
using System.Web.UI;
using WebGlobal;
using SimsObject;

namespace InformationWeb.Controls.TeacherWork
{
    /// <summary>
    /// Form thêm/sửa giờ NCKH giảng viên
    /// Công thức:
    ///   Tổng cộng giờ NCKH = SavePrev + ResearchNow
    ///   Nếu Tổng cộng >= Định mức NCKH -> SaveNext = Tổng cộng - Định mức, LackHour = 0
    ///   Nếu Tổng cộng <  Định mức NCKH -> SaveNext = 0, LackHour = Định mức - Tổng cộng
    ///   SavePrev tự động tính từ bản ghi năm trước trong vòng 5 năm (xử lý trong SP)
    /// </summary>
    public partial class TeachingTimeResearchEdit : ControlBase
    {
        #region Properties

        public long? TeachingTimeResearchID
        {
            get
            {
                if (ViewState["TeachingTimeResearchID" + this.ClientID] != null)
                    return Convert.ToInt64(ViewState["TeachingTimeResearchID" + this.ClientID]);
                return null;
            }
            set { ViewState["TeachingTimeResearchID" + this.ClientID] = value; }
        }

        public SIM_TeachingTimeResearch objData
        {
            get
            {
                if (Session["objTeachingTimeResearch" + this.ClientID] == null)
                    Session["objTeachingTimeResearch" + this.ClientID] = new SIM_TeachingTimeResearch();
                return Session["objTeachingTimeResearch" + this.ClientID] as SIM_TeachingTimeResearch;
            }
            set { Session["objTeachingTimeResearch" + this.ClientID] = value; }
        }

        #endregion

        #region Support Functions

        public void Clear()
        {
            TeachingTimeResearchID = null;
            objData = null;
            hidTeacherID.Value = "";
            hidYearID.Value = "";
            hidSemester.Value = "";
            lblTeacherName.Text = "";
            lblYearSemester.Text = "";
            txtTeachHour.Text = "";
            txtResearchHour.Text = "";
            txtSavePrev.Text = "";
            txtResearchNow.Text = "";
            txtResearchContent.Text = "";
            txtDecisionNo.Text = "";
            lblTotalHour.Text = "";
            lblSaveNext.Text = "";
            lblLackHour.Text = "";
            lblTitlePage.Text = "Thêm giờ NCKH giảng viên";
            udpAll.Update();
        }

        public void LoadInfo(long? teachingTimeResearchID)
        {
            if (teachingTimeResearchID != null)
                TeachingTimeResearchID = teachingTimeResearchID;
            LoadInfo();
        }

        public void LoadInfo()
        {
            if (TeachingTimeResearchID != null)
            {
                SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();
                DataTable dtbData = obj.GetDataTable("SIM_TeachingTimeResearch_Get",
                    "@TeachingTimeResearchID", TeachingTimeResearchID);

                if (dtbData != null && dtbData.Rows.Count > 0)
                {
                    DataRow drw = dtbData.Rows[0];
                    objData = new SIM_TeachingTimeResearch();
                    objData.TeachingTimeResearchID = TeachingTimeResearchID;
                    objData.TeacherID = drw["TeacherID"].ToString();
                    objData.YearID = Convert.ToInt32(drw["YearID"]);
                    objData.Semester = Convert.ToInt32(drw["Semester"]);

                    hidTeacherID.Value = objData.TeacherID;
                    hidYearID.Value = objData.YearID.ToString();
                    hidSemester.Value = objData.Semester.ToString();
                    lblTeacherName.Text = drw["TeacherName"].ToString();
                    lblYearSemester.Text = String.Format("{0} - HK {1}", objData.YearID, objData.Semester);
                    txtTeachHour.Text = FormatDecimal(drw["TeachHour"]);
                    txtResearchHour.Text = FormatDecimal(drw["ResearchHour"]);
                    txtSavePrev.Text = FormatDecimal(drw["SavePrev"]);
                    txtResearchNow.Text = FormatDecimal(drw["ResearchNow"]);
                    txtResearchContent.Text = drw["ResearchContent"] != DBNull.Value ? drw["ResearchContent"].ToString() : "";
                    txtDecisionNo.Text = drw["DecisionNo"] != DBNull.Value ? drw["DecisionNo"].ToString() : "";

                    // Hiển thị giá trị đã tính toán
                    lblTotalHour.Text = FormatDecimal(drw["TotalHour"]);
                    lblSaveNext.Text = FormatDecimal(drw["SaveNext"]);
                    lblLackHour.Text = FormatDecimal(drw["LackHour"]);

                    lblTitlePage.Text = "Sửa giờ NCKH giảng viên";
                    udpAll.Update();
                }
            }
        }

        public void LoadNew(object teacherID, object teacherName, object yearID, object semester)
        {
            Clear();
            hidTeacherID.Value = teacherID.ToString();
            hidYearID.Value = yearID.ToString();
            hidSemester.Value = semester.ToString();
            lblTeacherName.Text = teacherName != null ? teacherName.ToString() : teacherID.ToString();
            lblYearSemester.Text = String.Format("{0} - HK {1}", yearID, semester);
            lblTitlePage.Text = "Thêm giờ NCKH giảng viên";
            udpAll.Update();
        }

        private string FormatDecimal(object value)
        {
            if (value == null || value == DBNull.Value || value.ToString() == "")
                return "";
            return Convert.ToDecimal(value).ToString("0.##");
        }

        /// <summary>
        /// Parse chuỗi sang decimal. Trả về null nếu rỗng.
        /// Nếu không parse được (sai định dạng), hiển thị lỗi và trả về DBNull để phân biệt với null.
        /// </summary>
        private decimal? ParseDecimal(string text, string fieldName)
        {
            if (text == null || text.Trim() == "")
                return null;

            decimal decValue = 0;
            if (decimal.TryParse(text.Trim(), out decValue))
                return decValue;

            MsgBox.ShowWarning(String.Format("Trường [{0}] nhập sai định dạng số. Vui lòng nhập số thập phân (VD: 78.5)", fieldName));
            return null;
        }

        /// <summary>
        /// Validate tất cả các trường số thập phân trước khi lưu
        /// </summary>
        private bool ValidateDecimalInputs()
        {
            // Validate Định mức giờ NCKH
            if (txtResearchHour.Text.Trim() != "")
            {
                decimal testValue;
                if (!decimal.TryParse(txtResearchHour.Text.Trim(), out testValue))
                {
                    MsgBox.ShowWarning("Trường [Định mức giờ NCKH] nhập sai định dạng số!");
                    return false;
                }
            }

            // Validate Định mức giờ giảng dạy
            if (txtTeachHour.Text.Trim() != "")
            {
                decimal testValue;
                if (!decimal.TryParse(txtTeachHour.Text.Trim(), out testValue))
                {
                    MsgBox.ShowWarning("Trường [Định mức giờ giảng dạy] nhập sai định dạng số!");
                    return false;
                }
            }

            // Validate Giờ NCKH bảo lưu năm trước
            if (txtSavePrev.Text.Trim() != "")
            {
                decimal testValue;
                if (!decimal.TryParse(txtSavePrev.Text.Trim(), out testValue))
                {
                    MsgBox.ShowWarning("Trường [Giờ NCKH bảo lưu năm trước] nhập sai định dạng số!");
                    return false;
                }
            }

            // Validate Số giờ NCKH năm nay
            if (txtResearchNow.Text.Trim() != "")
            {
                decimal testValue;
                if (!decimal.TryParse(txtResearchNow.Text.Trim(), out testValue))
                {
                    MsgBox.ShowWarning("Trường [Số giờ NCKH năm nay] nhập sai định dạng số!");
                    return false;
                }
            }

            return true;
        }

        public bool SaveData()
        {
            if (hidTeacherID.Value.Trim() == "")
            {
                MsgBox.ShowWarning("Thiếu thông tin giảng viên!");
                return false;
            }
            if (hidYearID.Value.Trim() == "" || hidSemester.Value.Trim() == "")
            {
                MsgBox.ShowWarning("Thiếu thông tin năm học, học kỳ!");
                return false;
            }

            // Validate định dạng số thập phân
            if (!ValidateDecimalInputs())
                return false;

            objData.TeachingTimeResearchID = TeachingTimeResearchID;
            objData.TeacherID = hidTeacherID.Value.Trim();
            objData.YearID = Convert.ToInt32(hidYearID.Value);
            objData.Semester = Convert.ToInt32(hidSemester.Value);
            objData.TeachHour = ParseDecimal(txtTeachHour.Text, "Định mức giờ giảng dạy");
            objData.ResearchHour = ParseDecimal(txtResearchHour.Text, "Định mức giờ NCKH");
            objData.SavePrev = ParseDecimal(txtSavePrev.Text, "Giờ NCKH bảo lưu năm trước");
            objData.ResearchNow = ParseDecimal(txtResearchNow.Text, "Số giờ NCKH năm nay");
            objData.ResearchContent = txtResearchContent.Text.Trim();
            objData.DecisionNo = txtDecisionNo.Text.Trim();

            if (TeachingTimeResearchID == null)
            {
                objData.CreatedUser = User.UserName;
                if (!objData.Add())
                {
                    string strError = "Lỗi khi thêm dữ liệu!";
                    if (objData.ErrorException != null)
                        strError = strError + " " + objData.ErrorException.Message;
                    MsgBox.ShowError(strError);
                    return false;
                }
            }
            else
            {
                objData.UpdatedUser = User.UserName;
                if (!objData.Update())
                {
                    string strError = "Lỗi khi sửa dữ liệu!";
                    if (objData.ErrorException != null)
                        strError = strError + " " + objData.ErrorException.Message;
                    MsgBox.ShowError(strError);
                    return false;
                }
            }

            TeachingTimeResearchID = objData.TeachingTimeResearchID;
            return true;
        }

        public void ShowPopup()
        {
            string script = "var modalEl = document.getElementById('myModal_" + this.ClientID + "');" +
                "if(modalEl) { var bsModal = new bootstrap.Modal(modalEl); bsModal.show(); }";
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_OpenModal_" + this.ClientID, script, true);
        }

        public void ClosePopup()
        {
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_CloseModal_" + this.ClientID,
                "var m=document.getElementById('myModal_" + this.ClientID + "');if(m){var b=bootstrap.Modal.getInstance(m);if(b){b.hide();}}", true);
        }

        #endregion

        protected void Page_Load(object sender, EventArgs e)
        {
            if (User == null)
                return;
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                ClosePopup();
                if (SavedCompleted != null)
                    SavedCompleted(this, e);
            }
        }

        public event EventHandler SavedCompleted = null;
    }
}

