/// <summary>
/// Lấy SaveNext từ bản ghi gần nhất trong vòng 5 năm để làm SavePrev
/// </summary>
private void LoadSavePrev(string teacherID, int yearID)
{
    try
    {
        SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();
        DataTable dtbData = obj.GetDataTable("SIM_TeachingTimeResearch_GetSavePrev",
            "@TeacherID", teacherID,
            "@YearID", yearID);

        if (dtbData != null && dtbData.Rows.Count > 0)
        {
            txtSavePrev.Text = FormatDecimal(dtbData.Rows[0]["SavePrev"]);
        }
    }
    catch
    {
        // Nếu SP chưa được tạo thì bỏ qua, người dùng tự nhập
    }
}

